// npm run exercises:expect (PLAN §3.3, AGENTS.md "every expected output is generated by running code").
// For each exercise (and variant) folder, and each project, that has a `cases.yaml`:
//   1. build the reference solution natively with `gcc -std=c17 -Wall -Wextra -pedantic -Werror`
//      (src/runtime/c for learnc.h) and again with ASan+UBSan;
//   2. run every case (stdin, args) on both builds; the sanitizer build must be clean and agree with the plain one;
//   3. write `tests.json` (projects: `check.json`) with the real stdout and exit code.
// Authors never type an expectation: they list cases and run this.
//
//   <folder>/cases.yaml:
//     sources: [cash.c]        # optional, default: `file` of exercise.yaml
//     warnings: error          # optional, default: error
//     cases:
//       - name: 41 cents
//         stdin: "41\n"        # optional
//         args: [--flag]       # optional
//         hint: ...            # optional
//         timeoutMs: 2000      # optional, passed through to tests.json
import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { parse as parseYaml } from 'yaml';
import { ROOT } from '../shared/wasm-node';
import { discover, variantDirs } from './discover';

export const RUNTIME_DIR = path.join(ROOT, 'src/runtime/c');
const WARN_FLAGS = ['-std=c17', '-Wall', '-Wextra', '-pedantic', '-Werror'];
const SAN_FLAGS = ['-fsanitize=address,undefined', '-fno-omit-frame-pointer', '-fno-sanitize-recover=all'];
const SAN_REPORT = /AddressSanitizer|LeakSanitizer|UndefinedBehaviorSanitizer|runtime error:/;
const MAX_OUTPUT = 1 << 20;
const DEFAULT_TIMEOUT_MS = 10_000;

export interface Case { name: string; stdin?: string; args?: string[]; hint?: string; timeoutMs?: number }
export interface CasesFile { sources?: string[]; warnings?: 'error' | 'allow'; cases: Case[] }

export interface ExpectItem {
  /** "cash", "cash/variants/1", "project/mario-more" */
  id: string;
  dir: string;
  /** The file that was (or would be) written. */
  target: string;
  ok: boolean;
  /** true when the file's content changed (or, with check, would change). */
  changed: boolean;
  cases: number;
  problems: string[];
}

export interface ExpectOptions {
  contentRoot: string;
  module?: string;
  only?: string;
  cc?: string;
  /** Do not write; report items whose tests.json would change. */
  check?: boolean;
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Validates a parsed cases.yaml. */
export function validateCases(raw: unknown): { errors: string[]; cases?: CasesFile } {
  const errors: string[] = [];
  if (!isObj(raw)) return { errors: ['cases.yaml must be a mapping with a "cases" list'] };
  for (const k of Object.keys(raw)) if (!['sources', 'warnings', 'cases'].includes(k)) errors.push(`unknown key "${k}"`);
  if (raw.sources !== undefined && !(Array.isArray(raw.sources) && raw.sources.length > 0 && raw.sources.every(s => typeof s === 'string' && /\.c$/.test(s)))) {
    errors.push('"sources" must be a non-empty list of .c file names');
  }
  if (raw.warnings !== undefined && raw.warnings !== 'error' && raw.warnings !== 'allow') errors.push('"warnings" must be "error" or "allow"');
  if (!Array.isArray(raw.cases) || raw.cases.length === 0) errors.push('"cases" must be a non-empty list');
  else {
    const seen = new Set<string>();
    raw.cases.forEach((c, i) => {
      const where = `cases[${i}]`;
      if (!isObj(c)) { errors.push(`${where} must be a mapping`); return; }
      for (const k of Object.keys(c)) if (!['name', 'stdin', 'args', 'hint', 'timeoutMs'].includes(k)) errors.push(`${where}: unknown key "${k}"`);
      if (typeof c.name !== 'string' || c.name.trim() === '') errors.push(`${where}: "name" is required`);
      else if (seen.has(c.name)) errors.push(`${where}: duplicate name "${c.name}"`);
      else seen.add(c.name);
      if (c.stdin !== undefined && typeof c.stdin !== 'string') errors.push(`${where}: "stdin" must be a string`);
      if (c.args !== undefined && !(Array.isArray(c.args) && c.args.every(a => typeof a === 'string'))) errors.push(`${where}: "args" must be a list of strings`);
      if (c.hint !== undefined && typeof c.hint !== 'string') errors.push(`${where}: "hint" must be a string`);
      if (c.timeoutMs !== undefined && !(typeof c.timeoutMs === 'number' && c.timeoutMs > 0)) errors.push(`${where}: "timeoutMs" must be a positive number`);
    });
  }
  return errors.length ? { errors } : { errors, cases: raw as unknown as CasesFile };
}

const sh = (cmd: string, args: string[], opts: { input?: string; cwd?: string; timeout?: number; env?: NodeJS.ProcessEnv } = {}) =>
  spawnSync(cmd, args, { input: opts.input ?? '', cwd: opts.cwd, timeout: opts.timeout ?? 60_000, maxBuffer: MAX_OUTPUT, env: opts.env ?? process.env, encoding: 'utf8' });

interface Ran { stdout: string; stderr: string; exit: number }

/** Builds and runs one solution; returns tests.json content or the problems. */
function expectOne(cc: string, work: string, sourceDir: string, sources: string[], cases: Case[], allowWarnings: boolean): { tests?: Array<Record<string, unknown>>; problems: string[] } {
  const problems: string[] = [];
  const srcs = sources.map(s => path.join(sourceDir, s));
  const base = [...(allowWarnings ? ['-std=c17', '-Wall', '-Wextra', '-pedantic'] : WARN_FLAGS), '-I', RUNTIME_DIR, '-O0', '-g'];
  const plain = path.join(work, 'plain'), san = path.join(work, 'san');
  const b1 = sh(cc, [...base, ...srcs, '-o', plain, '-lm']);
  if (b1.error || b1.status !== 0) return { problems: [`the solution does not build with ${allowWarnings ? '' : '-Werror '}(-std=c17 -Wall -Wextra -pedantic):\n${(b1.error?.message ?? b1.stderr).trim()}`] };
  const b2 = sh(cc, [...base, ...SAN_FLAGS, ...srcs, '-o', san, '-lm']);
  if (b2.error || b2.status !== 0) return { problems: [`the solution does not build with ASan+UBSan:\n${(b2.error?.message ?? b2.stderr).trim()}`] };
  const env = { ...process.env, ASAN_OPTIONS: 'exitcode=86:detect_leaks=1:abort_on_error=0', UBSAN_OPTIONS: 'halt_on_error=1:print_stacktrace=0', LC_ALL: 'C' };
  const run = (exe: string, c: Case): Ran | string => {
    const r = sh(exe, c.args ?? [], { input: c.stdin ?? '', cwd: work, timeout: c.timeoutMs ?? DEFAULT_TIMEOUT_MS, env });
    // A program that never reads its stdin may exit before we finish writing it: that is not an error.
    if (r.error && (r.error as NodeJS.ErrnoException).code !== 'EPIPE') return `${r.error.message}`;
    if (r.status === null) return `killed by ${r.signal}`;
    return { stdout: r.stdout, stderr: r.stderr, exit: r.status };
  };
  const tests: Array<Record<string, unknown>> = [];
  for (const c of cases) {
    const a = run(plain, c), s = run(san, c);
    if (typeof a === 'string') { problems.push(`case "${c.name}": ${a}`); continue; }
    if (typeof s === 'string') { problems.push(`case "${c.name}" under ASan+UBSan: ${s}`); continue; }
    if (SAN_REPORT.test(s.stderr) || s.exit === 86) { problems.push(`case "${c.name}" fails under ASan+UBSan:\n${s.stderr.trim().split('\n').slice(0, 6).join('\n')}`); continue; }
    if (s.stdout !== a.stdout || s.exit !== a.exit) { problems.push(`case "${c.name}": the sanitizer build behaves differently from the plain build`); continue; }
    const run_: Record<string, unknown> = {};
    if (c.stdin !== undefined) run_.stdin = c.stdin;
    else run_.stdin = '';
    if (c.args && c.args.length) run_.args = c.args;
    if (c.timeoutMs !== undefined) run_.timeoutMs = c.timeoutMs;
    const t: Record<string, unknown> = { name: c.name, run: run_, expect: { stdout: a.stdout, exit: a.exit } };
    if (c.hint !== undefined) t.hint = c.hint;
    tests.push(t);
  }
  return { tests, problems };
}

/** Folders that have a cases.yaml: exercises, their variants, projects. */
export function expectAll(o: ExpectOptions): ExpectItem[] {
  const cc = o.cc ?? 'gcc';
  const d = discover(o.contentRoot, { module: o.module, only: o.only });
  const folders: Array<{ id: string; dir: string; project: boolean }> = [];
  for (const e of d.exercises) {
    folders.push({ id: e.id, dir: e.dir, project: false });
    for (const v of variantDirs(e.dir)) folders.push({ id: `${e.id}/variants/${v}`, dir: path.join(e.dir, 'variants', v), project: false });
  }
  for (const p of d.projects) folders.push({ id: `project/${p.id}`, dir: p.dir, project: true });

  const items: ExpectItem[] = [];
  const tmp = mkdtempSync(path.join(tmpdir(), 'exercises-expect-'));
  try {
    for (const f of folders) {
      const target = path.join(f.dir, f.project ? 'check.json' : 'tests.json');
      const item: ExpectItem = { id: f.id, dir: f.dir, target, ok: true, changed: false, cases: 0, problems: [] };
      const casesPath = path.join(f.dir, 'cases.yaml');
      if (!existsSync(casesPath)) { item.ok = false; item.problems.push('cases.yaml is missing'); items.push(item); continue; }
      const finish = () => { item.ok = item.problems.length === 0; items.push(item); };
      let raw: unknown;
      try { raw = parseYaml(readFileSync(casesPath, 'utf8')); } catch (e) { item.problems.push(`cases.yaml is not valid YAML: ${(e as Error).message}`); finish(); continue; }
      const v = validateCases(raw);
      if (!v.cases) { item.problems.push(...v.errors.map(e => `cases.yaml: ${e}`)); finish(); continue; }
      let file: string | undefined;
      try { file = (parseYaml(readFileSync(path.join(f.dir, 'exercise.yaml'), 'utf8')) as { file?: string } | null)?.file; } catch { /* reported below */ }
      const sources = v.cases.sources ?? (file ? [file] : []);
      if (sources.length === 0) { item.problems.push('no sources: set "sources" in cases.yaml or "file" in exercise.yaml'); finish(); continue; }
      if (sources.length > 1) { item.problems.push('more than one source file is not supported yet'); finish(); continue; }
      // exercises keep the reference as solution.c (learner file name differs); projects keep solution/<source>.
      const work = mkdtempSync(path.join(tmp, 'w-'));
      let sourceDir = f.dir;
      let solution = path.join(f.dir, 'solution.c');
      if (f.project) solution = path.join(f.dir, 'solution', sources[0]);
      else writeFileSync(path.join(work, sources[0]), readFileSync(solution));
      if (!existsSync(solution)) { item.problems.push(`${path.relative(f.dir, solution)} is missing`); finish(); continue; }
      sourceDir = f.project ? path.join(f.dir, 'solution') : work;
      const r = expectOne(cc, work, sourceDir, sources, v.cases.cases, v.cases.warnings === 'allow');
      item.problems.push(...r.problems);
      item.cases = v.cases.cases.length;
      if (r.tests && r.problems.length === 0) {
        const spec = { version: 1, sources, warnings: v.cases.warnings ?? 'error', tests: r.tests };
        const next = `${JSON.stringify(spec, null, 2)}\n`;
        const prev = existsSync(target) ? readFileSync(target, 'utf8') : undefined;
        item.changed = prev !== next;
        if (item.changed && !o.check) writeFileSync(target, next);
      }
      finish();
    }
  } finally { rmSync(tmp, { recursive: true, force: true }); }
  return items;
}

